//--------------------------------------------------------------------------------------------------

@MainActor func transient_ComponentSymbolInProject_selectionDisplay (
       _ prefs_selectionHiliteColor : NSColor,                       
       _ prefs_pinNameFont : NSFont,                                 
       _ prefs_schematicBackColor : NSColor,                         
       _ self_mDisplayComponentNameOffsetX : CanariLength,           
       _ self_mDisplayComponentNameOffsetY : CanariLength,           
       _ self_mDisplayComponentValue : Bool,                         
       _ self_mDisplayComponentValueOffsetX : CanariLength,          
       _ self_mDisplayComponentValueOffsetY : CanariLength,          
       _ self_symbolInfo : ComponentSymbolInfo,                      
       _ self_mRotation : QuadrantRotation
) -> EBShape {
//--- START OF USER ZONE 2
        var shape = EBShape ()
      //--- Frame symbol
        var strokeBezierPath = BezierPath ()
        strokeBezierPath.append (self_symbolInfo.strokeBezierPath)
        strokeBezierPath.lineWidth = SCHEMATIC_HILITE_WIDTH.ptValue
        shape.add (stroke: [strokeBezierPath], prefs_selectionHiliteColor)
      //--- Line from center to component value
        let symbolCenter = self_symbolInfo.center.ptValue
        let componentValueCenter = CanariPoint (
          x: self_symbolInfo.center.x + self_mDisplayComponentValueOffsetX,
          y: self_symbolInfo.center.y + self_mDisplayComponentValueOffsetY
        )
        if self_mDisplayComponentValue {
          var bp = BezierPath ()
          bp.move (to: symbolCenter)
          bp.line (to: componentValueCenter.ptValue)
          bp.lineWidth = SCHEMATIC_HILITE_WIDTH.ptValue
          bp.lineCapStyle = .round
          bp.lineJoinStyle = .round
          shape.add (stroke: [bp], prefs_selectionHiliteColor)
        }
      //--- line from center to name
        let componentNameCenter = CanariPoint (
          x: self_symbolInfo.center.x + self_mDisplayComponentNameOffsetX,
          y: self_symbolInfo.center.y + self_mDisplayComponentNameOffsetY
        )
        do{
          var bp = BezierPath ()
          bp.move (to: symbolCenter)
          bp.line (to: componentNameCenter.ptValue)
          bp.lineWidth = SCHEMATIC_HILITE_WIDTH.ptValue
          bp.lineCapStyle = .round
          bp.lineJoinStyle = .round
          shape.add (stroke: [bp], prefs_selectionHiliteColor)
        }
      //--- Component value knob
        if self_mDisplayComponentValue {
          let value = (self_symbolInfo.componentValue != "") ? self_symbolInfo.componentValue : "No value"
          let componentValueShape = EBShape (
            textKnob: value,
            componentValueCenter.ptValue,
            prefs_pinNameFont,
            foreColor: .black,
            backColor: prefs_schematicBackColor,
            .center,
            .center,
            .circ,
            knobIndex: SYMBOL_IN_SCHEMATICS_COMPONENT_VALUE_KNOB
          )
          shape.add (componentValueShape)
        }
      //--- Component name knob
        do{
          shape.add (textKnob: 
            self_symbolInfo.componentName,
            componentNameCenter.ptValue,
            prefs_pinNameFont,
            foreColor: .black,
            backColor: prefs_schematicBackColor,
            .center,
            .center,
            .circ,
            knobIndex: SYMBOL_IN_SCHEMATICS_COMPONENT_NAME_KNOB
          )
        }
      //--- symbol rotation knob
        let symbolRotationInRadians = CGFloat (self_mRotation.rawValue) * .pi / 2.0
      //--- Center knob
        shape.add (knobAt:  symbolCenter, knobIndex: SYMBOL_IN_SCHEMATICS_CENTER_KNOB, .rect, SCHEMATIC_KNOB_SIZE.ptValue)
      //--- Line from center to rotation knob
        let d = CanariLength.mil (200.0)
        let rotationKnobCenter = NSPoint (
          x: self_symbolInfo.center.x + d * cos (symbolRotationInRadians),
          y: self_symbolInfo.center.y + d * sin (symbolRotationInRadians)
        )
        var bp = BezierPath ()
        bp.move (to: symbolCenter)
        bp.line (to: rotationKnobCenter)
        bp.lineWidth = SCHEMATIC_HILITE_WIDTH.ptValue
        bp.lineCapStyle = .round
        bp.lineJoinStyle = .round
        shape.add (stroke: [bp], prefs_selectionHiliteColor)
        shape.add (
          knobAt: rotationKnobCenter,
          knobIndex: SYMBOL_IN_SCHEMATICS_ROTATION_KNOB,
          .circ,
          SCHEMATIC_KNOB_SIZE.ptValue
        )
      //---
        return shape
//--- END OF USER ZONE 2
}

